"""Run diagnostic probes against production logic in temporary copies; does not edit app source.
Usage: python3 diagnostic-reproduction.py /absolute/path/to/repository
Requires Xcode Swift and macOS frameworks. Probes intentionally confirm defects, not correctness.
"""
from pathlib import Path
import tempfile, subprocess, sys
root=Path(sys.argv[1]).resolve()
src=root/'CinematicCoreMacOS/CinematicCoreMacOS'
work=Path(tempfile.mkdtemp(prefix='alfie-probes-'))
parts={'PersonDetector': '\n    static func diagnosticRun() {\n        let reference = CGRect(x:0.47,y:0.3,width:0.06,height:0.5)\n        let cases: [(String, CGRect)] = [\n            ("probation bypass", reference.offsetBy(dx:0.10,dy:0)),\n            ("distance rejection bypass", reference.offsetBy(dx:0.13,dy:0)),\n            ("size rejection bypass", CGRect(x:0.4,y:0.15,width:0.2,height:0.8))\n        ]\n        for (label, candidate) in cases {\n            let detector = PersonDetector()\n            let id = UUID()\n            detector.lockedTargetID = id\n            detector.trackedPersons[id] = TrackedPerson(id:id,firstSeen:0,lastSeen:10,lastBoundingBox:reference,confidence:1)\n            let a = resolveLockedAssignment(detections:[candidate],referenceBox:reference,lockVelocityMagnitude:0,timeSinceLockSeen:0.02,otherTrackBoxes:[],probation:nil)\n            let b = detector.assignTracks(detections:[VNHumanObservation(boundingBox:candidate)],timestamp:10.02)\n            print("\\(label): Pass A accepted=\\(a.assignedIndex != nil), full matcher rebound locked UUID=\\(b[0] == id)")\n            precondition(a.assignedIndex == nil && b[0] == id)\n        }\n        print("All 3 bypass reproductions confirmed using production assignTracks and resolver.")\n    }\n', 'ShotComposer': '\n    static func diagnosticRun() {\n        let c = ShotComposer(), a = UUID(), b = UUID(), d = UUID()\n        c.lockState = .wideWaiting(gallery: FaceSignatureGallery())\n        for (id,score) in [(a,Float(0.1)),(b,Float(0.5)),(d,Float(0.6))] {\n            c.applyReacquisitionResult(candidateID:id,bestPrintDistance:score,landmarkDistance:0,consecutiveTarget:3)\n        }\n        print("Reacquisition: one observation each of A,B,C -> A count=\\(c.reacquisitionConsecutive[a] ?? 0), pending A=\\(c.pendingReacquisition == a)")\n        precondition(c.pendingReacquisition == a)\n        let q = ShotComposer(), id = UUID()\n        let p = PersonDetector.DetectedPerson(id:id,boundingBox:CGRect(x:0.4,y:0.2,width:0.1,height:0.5),confidence:1,timestamp:0,poseKeypoints:nil,faceBoundingBox:nil,faceLandmarkRatios:nil)\n        q.lockState = .acquiring(targetID:id,gallery:FaceSignatureGallery(),sinceTime:0)\n        _ = q.tick(detections:[p],timestamp:120,pixelBuffer:nil,isFresh:true)\n        print("Body visible without face at 120s: acquiring=\\(q.isAcquiring)")\n        precondition(q.isAcquiring)\n        _ = q.tick(detections:[],timestamp:120.02,pixelBuffer:nil,isFresh:true)\n        print("First missing frame after 120s: state=\\(q.lockStateName)")\n        precondition(!q.isAcquiring)\n        let hold = ShotComposer()\n        hold.lockState = .tracking(targetID:id,gallery:FaceSignatureGallery())\n        _ = hold.tick(detections:[],timestamp:0,pixelBuffer:nil)\n        _ = hold.tick(detections:[],timestamp:9.9,pixelBuffer:nil)\n        print("Missing subject at 9.9s: holding=\\(hold.isHolding)")\n        _ = hold.tick(detections:[],timestamp:10.01,pixelBuffer:nil)\n        print("Missing subject at 10.01s: wideWaiting=\\(hold.isWideWaiting)")\n        print("Composer diagnosis checks complete.")\n    }\n'}
main='import Foundation\nMainActor.assumeIsolated {\n PersonDetector.diagnosticRun()\n ShotComposer.diagnosticRun()\n let person = PersonDetector.DetectedPerson(id:UUID(),boundingBox:CGRect(x:0.4,y:0.1,width:0.2,height:0.8),confidence:1,timestamp:0,poseKeypoints:nil,faceBoundingBox:nil,faceLandmarkRatios:nil)\n for preset in ShotComposer.Config.ShotPreset.allCases {\n  let c = ShotComposer(); c.config.shotPreset = preset\n  print("Large subject preset \\(preset): crop height \\(c.compose(person:person)!.size.height)")\n }\n}\n'
for name, probe in parts.items():
    s=(src/(name+'.swift')).read_text(); pos=s.rfind('\n}')
    (work/(name+'.swift')).write_text(s[:pos]+probe+s[pos:])
(work/'main.swift').write_text(main)
subprocess.run(['swiftc','-module-cache-path',str(work/'modules'),'-swift-version','5',str(work/'PersonDetector.swift'),str(work/'ShotComposer.swift'),str(src/'FaceSignatureExtractor.swift'),str(src/'CropEngine.swift'),str(work/'main.swift'),'-o',str(work/'check')],check=True)
subprocess.run([str(work/'check')],check=True)
print('Temporary evidence:',work)
